import json
from collections import Counter

with open('/home/ubuntu/runs/paper/qwen-h-in-glm-hpl-u1-light/frozen/stream-000/play/users/u062/system/state/workspace/programs/task-5c839a47.json', 'r') as f:
    data = json.load(f)
demo_pairs = data['demo_pairs']

def find_dot_color(grid):
    counts = Counter()
    for r in grid:
        for c in r:
            counts[c] += 1
    # Find the "dot" color - the less common one, but at least 2
    sorted_items = sorted(counts.items(), key=lambda x: x[1])
    dot = sorted_items[0][0]  # least common
    return dot

def should_become_3_grid(grid, r, c, dot):
    # Check if between dots on same row
    dots_row = [col for col, v in enumerate(grid[r]) if v == dot]
    row_between = len(dots_row) >= 2 and min(dots_row) < c < max(dots_row)

    # Check if between dots on same column
    dots_col = [row for row, g in enumerate(grid) if g[c] == dot]
    col_between = len(dots_col) >= 2 and min(dots_col) < r < max(dots_col)

    return row_between or col_between

# Verify demo pair 0
inp0 = demo_pairs[0]['input']
out0 = demo_pairs[0]['output']
dot0 = 5

all_ok = True
for r in range(len(inp0)):
    for c in range(len(inp0[0])):
        inp_val = inp0[r][c]
        out_val = out0[r][c]

        # If it's a dot, it should stay the same
        if inp_val == dot0:
            if out_val != dot0:
                all_ok = False
                print(f"Error: dot changed at ({r},{c}): {inp_val} -> {out_val}")
            continue

        # If it should become 3, check output
        must_be_3 = should_become_3_grid(inp0, r, c, dot0)
        if must_be_3:
            if out_val != 3:
                all_ok = False
                print(f"Error: should be 3 at ({r},{c}): got {out_val}")
        else:
            if out_val != inp_val:
                all_ok = False
                print(f"Error: should stay at ({r},{c}): {inp_val} -> {out_val}")

if all_ok:
    print("Demo pair 0 PASSED!")

# Verify demo pair 1
inp1 = demo_pairs[1]['input']
out1 = demo_pairs[1]['output']
dot1 = find_dot_color(inp1)

all_ok = True
for r in range(len(inp1)):
    for c in range(len(inp1[0])):
        inp_val = inp1[r][c]
        out_val = out1[r][c]

        if inp_val == dot1:
            if out_val != dot1:
                all_ok = False
                print(f"Error: dot changed at ({r},{c}): {inp_val} -> {out_val}")
            continue

        must_be_3 = should_become_3_grid(inp1, r, c, dot1)
        if must_be_3:
            if out_val != 3:
                all_ok = False
                print(f"Error: should be 3 at ({r},{c}): got {out_val}")
        else:
            if out_val != inp_val:
                all_ok = False
                print(f"Error: should stay at ({r},{c}): {inp_val} -> {out_val}")

if all_ok:
    print("Demo pair 1 PASSED!")
else:
    print(f"Demo pair 1 FAILED, dot={dot1}")

# Verify demo pair 2
inp2 = demo_pairs[2]['input']
out2 = demo_pairs[2]['output']
dot2 = find_dot_color(inp2)
print(f"Demo pair 2: dot={dot2}")

all_ok = True
for r in range(len(inp2)):
    for c in range(len(inp2[0])):
        inp_val = inp2[r][c]
        out_val = out2[r][c]

        if inp_val == dot2:
            if out_val != dot2:
                all_ok = False
            continue

        must_be_3 = should_become_3_grid(inp2, r, c, dot2)
        if must_be_3:
            if out_val != 3:
                all_ok = False
        else:
            if out_val != inp_val:
                all_ok = False

if all_ok:
    print("Demo pair 2 PASSED!")
else:
    print(f"Demo pair 2 FAILED")

